(function(){'use strict';
 const page=(document.body.dataset.page||'').toLowerCase();
 // Home and authentication pages own their layouts. Never inject the global navigation shell there.
 if(document.body.classList.contains('home-page')||['home','login','signup'].includes(page)||document.body.classList.contains('login-page')||document.body.classList.contains('signup-page')) return;
 document.body.classList.add('nx-global-shell');
 const items=[['home','Home.html','Home'],['campus','campus.html','Campus'],['academics','academics.html','Academics'],['ai','ai-assistant.html','Study Assistant'],['career','career.html','Career'],['planner','planner.html','Planner'],['community','community.html','Community'],['dashboard','dashboard.html','Dashboard'],['hub','nexzo-hub.html','NEXZO Hub'],['settings','settings.html','Settings'],['profile','profile.html','Profile']];
 const current=k=>page===k||(k==='ai'&&['ai','assistant'].includes(page));
 const drawerLinks=items.map(([k,h,l],i)=>`<a href="${h}" ${current(k)?'aria-current="page"':''}><i>${String(i+1).padStart(2,'0')}</i><span>${l}</span><b>↗</b></a>`).join('');
 const trigger=document.createElement('button'); trigger.className='nx-slider-trigger';trigger.type='button';trigger.setAttribute('aria-label','Open NEXZO navigation');trigger.setAttribute('aria-expanded','false');trigger.innerHTML='<span></span><span></span>';
 const drawer=document.createElement('aside');drawer.className='nx-shell-drawer';drawer.setAttribute('aria-hidden','true');drawer.inert=true;drawer.id='nx-navigation-drawer';trigger.setAttribute('aria-controls',drawer.id);drawer.innerHTML=`<div class="nx-shell-drawer-head"><a class="nx-shell-brand" href="Home.html"><img src="favicon.png" alt=""><span><strong>NEXZO</strong><small>PERSONALIZED RECOMMENDER</small></span></a><button type="button" aria-label="Close navigation">×</button></div><div class="nx-drawer-label">NAVIGATE / NEXZO</div><nav>${drawerLinks}</nav>`;
 const backdrop=document.createElement('div');backdrop.className='nx-shell-backdrop';
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','nx-global-path');svg.setAttribute('viewBox','0 0 1000 800');svg.setAttribute('preserveAspectRatio','none');svg.setAttribute('aria-hidden','true');svg.innerHTML='<path class="nx-path-main" d="M -80 650 L 190 650 L 420 280 L 650 280 L 1080 70"/><path class="nx-path-echo" d="M -80 660 L 200 660 L 430 290 L 660 290 L 1080 80"/><path class="nx-path-thread" d="M 90 -50 C 260 160 170 420 420 520 S 760 620 1040 760"/><path class="nx-path-thread nx-path-thread-2" d="M -40 180 C 240 60 520 210 1040 120"/><circle class="nx-path-spark" cx="650" cy="280" r="3.5"/>';
 const brand=document.createElement('a');brand.className='nx-global-brand';brand.href='Home.html';brand.setAttribute('aria-label','NEXZO Home');brand.innerHTML=`<img class="nx-global-brand-mark" src="favicon.png" alt=""><span class="nx-global-brand-copy"><img class="nx-global-brand-wordmark" src="assets/nexzo-wordmark-cream.svg?v=15" alt="NEXZO"><small>PERSONALIZED RECOMMENDER</small>${['ai','assistant'].includes(page)?'<em><i></i> STUDY ASSISTANT</em>':''}</span>`;
 document.body.prepend(svg);document.body.prepend(backdrop);document.body.prepend(drawer);document.body.prepend(brand);document.body.prepend(trigger);
 if(['ai','assistant'].includes(page)){const tools=document.createElement('section');tools.className='nx-assistant-drawer-tools';tools.innerHTML='<small>STUDY ASSISTANT</small><div class="nx-assistant-tool-grid"><button type="button" data-nx-assistant="new">＋ New chat</button><button type="button" data-nx-assistant="history">◷ History</button><button type="button" data-nx-assistant="tools">✦ Study tools</button><button type="button" data-nx-assistant="uploads">⌇ Uploads</button><a href="planner.html">▦ Planner</a><a href="academics.html">↗ Academics</a></div>';drawer.appendChild(tools);tools.addEventListener('click',e=>{const b=e.target.closest('[data-nx-assistant]');if(!b)return;const map={new:'newChat',history:'historyOpen',tools:'composerToolsBtn',uploads:'fileInput'};toggle(false);document.getElementById(map[b.dataset.nxAssistant])?.click()});}
 const titles={campus:['CAMPUS','DISCOVERY / BEYOND THE CLASSROOM'],academics:['ACADEMICS','KNOWLEDGE / BUILD WHAT YOU KNOW'],ai:['STUDY ASSISTANT','INTELLIGENCE / CONTEXT IN MOTION'],assistant:['STUDY ASSISTANT','INTELLIGENCE / CONTEXT IN MOTION'],career:['CAREER','DIRECTION / DEFINE WHAT IS NEXT'],planner:['PLANNER','STRUCTURE / TURN INTENT INTO TIME'],community:['COMMUNITY','CONNECTION / SHARED MOMENTUM'],dashboard:['DASHBOARD','NEXT ACTION / MOVE WITH PURPOSE'],hub:['NEXZO HUB','EVOLVE / PROGRESS MADE VISIBLE'],settings:['SETTINGS','CONTROL / YOUR NEXZO'],profile:['PROFILE','IDENTITY / YOUR PROGRESS']};
 const key=page||'home', info=titles[key]; if(info && !['ai','assistant'].includes(key)){const main=document.querySelector('main.main, main');if(main){const mast=document.createElement('section');mast.className='nx-page-mast';mast.innerHTML=`<div class="nx-page-index">${String(Math.max(1,items.findIndex(x=>x[0]===key)+1)).padStart(2,'0')} / ${info[1]}</div><h1>${info[0]}</h1><div class="nx-page-rule"><span></span><b>SCROLL TO EXPLORE</b></div>`;main.prepend(mast)}}
 function toggle(open){const wasOpen=drawer.classList.contains('is-open');drawer.inert=!open;drawer.classList.toggle('is-open',open);backdrop.classList.toggle('is-open',open);drawer.setAttribute('aria-hidden',String(!open));trigger.setAttribute('aria-expanded',String(open));document.documentElement.classList.toggle('nx-nav-open',open);if(open)drawer.querySelector('button').focus();else if(wasOpen&&!document.body.classList.contains('ai-clean-page'))trigger.focus()} window.NEXZONavigation={open:()=>toggle(true),close:()=>toggle(false),toggle:()=>toggle(!drawer.classList.contains('is-open'))};
 trigger.addEventListener('click',()=>toggle(!drawer.classList.contains('is-open')));document.addEventListener('click',e=>{const menu=e.target.closest('[data-nx-global-menu]');if(!menu)return;e.preventDefault();e.stopPropagation();toggle(!drawer.classList.contains('is-open'));});drawer.querySelector('button').addEventListener('click',()=>toggle(false));backdrop.addEventListener('click',()=>toggle(false));addEventListener('keydown',e=>{if(e.key==='Escape')toggle(false);if(e.key==='Tab'&&drawer.classList.contains('is-open')){const nodes=[...drawer.querySelectorAll('a[href],button:not([disabled])')];const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
 const path=svg.querySelector('.nx-path-main'),echo=svg.querySelector('.nx-path-echo'),thread=svg.querySelector('.nx-path-thread'),thread2=svg.querySelector('.nx-path-thread-2'),spark=svg.querySelector('.nx-path-spark'),reduced=matchMedia('(prefers-reduced-motion: reduce)');let raf=0,lastFrame=0;
 function draw(now=performance.now()){raf=0;if(reduced.matches||document.hidden)return;const max=Math.max(1,document.documentElement.scrollHeight-innerHeight),p=Math.min(1,Math.max(0,scrollY/max)),t=now/1000,wave=Math.sin(p*Math.PI*2+t*.34),wave2=Math.cos(p*Math.PI*1.5+t*.27),drift=Math.sin(t*.22)*34,drift2=Math.cos(t*.18)*26;const y1=690-270*p+drift*.24,y2=360+145*wave+drift2*.72,y3=330-105*wave2-drift*.24,y4=145+350*p+drift2*.48;path.setAttribute('d',`M -80 ${y1} L ${190+100*p+drift*.18} ${y1} L ${420-90*p} ${y2} L ${650+100*p+drift*.22} ${y3} L 1080 ${y4}`);echo.setAttribute('d',`M -80 ${y1+11} L ${200+100*p+drift*.18} ${y1+11} L ${430-90*p} ${y2+11} L ${660+100*p+drift*.22} ${y3+11} L 1080 ${y4+11}`);thread.setAttribute('d',`M ${90+90*p+drift*.2} -50 C ${260+140*wave} ${160+100*p+drift2} ${170+100*p} ${420-120*wave} ${420+180*p} ${520-80*p+drift*.3} S ${760-100*p} ${620+80*wave} 1040 ${760-260*p+drift2}`);if(thread2)thread2.setAttribute('d',`M -40 ${180+drift2*.35} C ${240+drift*.4} ${60+drift*.25} ${520-drift*.25} ${210+drift2*.4} 1040 ${120+drift*.2}`);spark.setAttribute('cx',String(650+100*p+drift*.22));spark.setAttribute('cy',String(y3));document.documentElement.style.setProperty('--nx-grid-y',`${-p*110+drift*.12}px`);document.documentElement.style.setProperty('--nx-scroll',p.toFixed(3));lastFrame=now}
 function loop(now){if(document.hidden||reduced.matches){raf=0;return}if(now-lastFrame>32)draw(now);raf=requestAnimationFrame(loop)}
 function ensureLoop(){if(!raf&&!document.hidden&&!reduced.matches)raf=requestAnimationFrame(loop)}
 addEventListener('scroll',()=>{draw();ensureLoop()},{passive:true});addEventListener('resize',()=>{draw();ensureLoop()},{passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden&&raf){cancelAnimationFrame(raf);raf=0}else ensureLoop()});reduced.addEventListener?.('change',()=>{if(reduced.matches&&raf){cancelAnimationFrame(raf);raf=0}else ensureLoop()});addEventListener('pointermove',e=>{if(reduced.matches||document.hidden)return;document.documentElement.style.setProperty('--nx-mx',`${e.clientX/innerWidth*100}%`);document.documentElement.style.setProperty('--nx-my',`${e.clientY/innerHeight*100}%`)},{passive:true});draw();ensureLoop();
})();
